<?php
declare(strict_types=1); require __DIR__.'/../config/auth.php'; require __DIR__.'/../config/database.php'; require __DIR__.'/../config/product_types.php'; require_admin(); if(empty($_SESSION['admin_csrf']))$_SESSION['admin_csrf']=bin2hex(random_bytes(32));seed_product_type_catalog();$msg='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['admin_csrf'],(string)($_POST['csrf']??'')))$err='Güvenlik doğrulaması geçersiz.';else{try{$steps=json_decode((string)$_POST['steps'],true);$fields=json_decode((string)$_POST['fields'],true);if(!is_array($steps)||!is_array($fields))throw new RuntimeException('Adımlar ve alanlar geçerli JSON olmalıdır.');db()->prepare('UPDATE product_type_catalog SET label=?,unit=?,steps=?::jsonb,fields=?::jsonb,room_setup=?,hint=?,is_active=?,sort_order=?,updated_at=now() WHERE code=?')->execute([trim((string)$_POST['label']),trim((string)$_POST['unit']),json_encode($steps,JSON_UNESCAPED_UNICODE),json_encode($fields,JSON_UNESCAPED_UNICODE),isset($_POST['room_setup']),trim((string)$_POST['hint']),isset($_POST['is_active']),(int)$_POST['sort_order'],$_POST['code']]);$msg='Şablon kaydedildi.';}catch(Throwable $e){$err=$e->getMessage();}}}$rows=db()->query('SELECT * FROM product_type_catalog ORDER BY sort_order,code')->fetchAll();?><!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ürün şablonları</title><style>body{font-family:Arial;background:#f7f7f2;color:#10211f;margin:0}.w{width:min(1000px,calc(100% - 30px));margin:35px auto}.c{background:#fff;border:1px solid #ddd;padding:18px;margin:16px 0}.f{display:grid;gap:9px}.r{display:grid;grid-template-columns:1fr 1fr 100px;gap:9px}input,textarea,button{padding:9px;font:inherit;border:1px solid #ddd}textarea{min-height:100px;font-family:monospace}button{background:#10211f;color:#fff;font-weight:bold}.ok{background:#e6f8c7;padding:9px}.er{background:#ffe2de;padding:9px}</style></head><body><main class="w"><a href="/nexustraveltech/admin/kontrol-merkezi">← Kontrol merkezi</a><h1>Ürün türleri ve form şablonları</h1><p>Bu ekran, tedarikçi ilan formundaki adımlar ve alanları veritabanından yönetir.</p><?php if($msg):?><p class="ok"><?=htmlspecialchars($msg)?></p><?php endif;?><?php if($err):?><p class="er"><?=htmlspecialchars($err)?></p><?php endif;?><?php foreach($rows as $x):?><form class="c f" method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['admin_csrf'])?>"><input type="hidden" name="code" value="<?=htmlspecialchars($x['code'])?>"><h2><?=htmlspecialchars($x['code'])?></h2><div class="r"><input name="label" value="<?=htmlspecialchars($x['label'])?>"><input name="unit" value="<?=htmlspecialchars($x['unit'])?>"><input name="sort_order" type="number" value="<?=$x['sort_order']?>"></div><input name="hint" value="<?=htmlspecialchars($x['hint'])?>"><label>Adımlar (JSON)<textarea name="steps"><?=htmlspecialchars($x['steps'])?></textarea></label><label>Alanlar (JSON)<textarea name="fields"><?=htmlspecialchars($x['fields'])?></textarea></label><label><input type="checkbox" name="room_setup" <?=$x['room_setup']?'checked':''?>> Oda/villa kurulumu</label><label><input type="checkbox" name="is_active" <?=$x['is_active']?'checked':''?>> Aktif</label><button>Kaydet</button></form><?php endforeach;?></main><?php require_once __DIR__.'/../config/ai_widget.php'; ai_widget('/nexustraveltech/admin/ai-chat','admin_csrf'); ?></body></html>
